import json,time,urllib.request,urllib.error
B="http://localhost:8080"
tok=None
def get(path,post=False):
    global tok
    for i in range(200):
        if tok is None and path!="/token":
            tok=get("/token",True)["token"]
        h={"Authorization":"Bearer "+tok} if tok and path!="/token" else {}
        r=urllib.request.Request(B+path,headers=h,method="POST" if post else "GET",data=b"" if post else None)
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404: return None
            if e.code==401: tok=None; continue
            w=e.headers.get("Retry-After")
            try: w=float(w)
            except: w=None
            if w is None:
                try: w=float(json.loads(body).get("retry_after",1))
                except: w=1
            print(e.code,body[:100],w,flush=True); time.sleep(w)
        except Exception as e:
            print("err",e,flush=True); time.sleep(1)
    raise SystemExit("fail "+path)
from datetime import datetime,timezone
seen={};dup=0;p=1
while p:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen: dup+=1
        else: seen[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else 0
print(len(seen),dup)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: t=t.replace(tzinfo=timezone.utc)
    if not lo<=t<hi: continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    if cust[c] is None: print("missing",c); continue
    a=o["amount_cents"]*(100-cust[c]["discount_pct"])
    reg[cust[c]["region"]]+=(a+50)//100;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dup,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
